The new JavaScript code in these blocks uses `var` and `function` expressions for callbacks. This is inconsistent with the surrounding code in this file, which generally uses modern JavaScript features like `const`/`let` and arrow functions. Adopting a consistent style improves readability and maintainability. `const` and `let` are block-scoped and generally safer than function-scoped `var`.

```javascript
// Clone Install Box — single source of truth for install commands
// The hero section (#install-box-source) is the canonical install component.
// The CTA section (#install-box-clone) receives a deep clone so commands
// only need to be updated in one place.
(function() {
    const source = document.getElementById('install-box-source');
    const target = document.getElementById('install-box-clone');
    if (!source || !target) return;

    const clone = source.cloneNode(true);
    // Remove the source id to avoid duplicate IDs in the DOM
    clone.removeAttribute('id');
    // Strip all id attributes from cloned children (e.g. copyBtnCurl)
    clone.querySelectorAll('[id]').forEach(el => {
        el.removeAttribute('id');
    });
    target.replaceWith(clone);
})();

// Install Tabs — scoped per install-box so each operates independently
(function() {
    document.querySelectorAll('.install-box').forEach(box => {
        const tabs = box.querySelectorAll('.install-tab');
        const panels = box.querySelectorAll('.install-panel');

        tabs.forEach(tab => {
            tab.addEventListener('click', function() {
                const targetPanel = this.dataset.tab;

                // Update tabs within this box only
                tabs.forEach(t => {
                    t.classList.remove('active');
                    t.setAttribute('aria-selected', 'false');
