                this.classList.add('active');
                this.setAttribute('aria-selected', 'true');

                // Update panels within this box only
                panels.forEach(p => {
                    p.classList.remove('active');
                    if (p.dataset.panel === targetPanel) {
                        p.classList.add('active');
                    }
                });
            });
        });
    });
